<?php require 'db.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT o.order_id,o.customer_name,o.email,o.total_amount,o.status,p.method,p.status AS payment_status FROM orders o LEFT JOIN payments p ON p.order_id=o.order_id WHERE o.order_id=?");$s->execute([$id]);$o=$s->fetch();if(!$o){header('Location:index.php');exit;}$paid=$o['status']==='Paid';$statusText=$paid?'Payment confirmed':('Order status: '.$o['status']);?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order Status | Ceylon Spice Hub</title><link rel="stylesheet" href="style.css"></head><body><main class="success-page"><div class="success-card"><div class="check"><?=$paid?'✓':'✓'?></div><p class="eyebrow"><?=e($o['method']??'ORDER')?></p><h1><?= $paid ? 'Payment successful!' : 'Order received!' ?></h1><p><?= $paid ? 'Your PayHere payment has been verified and your order is confirmed.' : 'Your order has been received successfully. We\'ll prepare your spices with care.' ?></p><div class="order-number">Order #<?=e((string)$o['order_id'])?></div><div class="success-total"><span>Order Total</span><b><?=money((float)$o['total_amount'])?></b></div><p class="small"><b><?=e($statusText)?></b> · Confirmation recorded for <?=e($o['email'])?>.</p><a class="btn btn-primary" href="index.php">BACK TO SHOP</a></div></main><style>.success-page{min-height:100vh;background:#fbf8f1;display:grid;place-items:center;padding:20px}.success-card{background:#fff;border:1px solid #e7e3da;text-align:center;padding:55px 40px;max-width:600px;width:100%;box-shadow:0 20px 50px #1232}.check{margin:auto;width:65px;height:65px;border-radius:50%;background:#0d5135;color:#fff;font-size:35px;padding-top:9px}.success-card h1{font:700 38px "Playfair Display";margin:8px}.success-card>p:not(.eyebrow):not(.small){color:#68706b;font-size:13px;margin:15px auto;max-width:430px}.order-number{background:#fbf8f1;padding:13px;font-weight:700;margin:22px 0}.success-total{display:flex;justify-content:space-between;border-top:1px solid #e7e3da;border-bottom:1px solid #e7e3da;padding:15px 0;font-size:12px}.success-total b{font-size:15px}.small{font-size:9px;color:#777;margin:15px}</style></body></html>
